INSERT INTO `platform_rbac_template` VALUES ('builtin_tenant_ns_admin', 'tenant-namespace-admin', '内置模板：命名空间内全量权限（默认）', '{\"rules\":[{\"apiGroups\":[\"\"],\"resources\":[\"pods\",\"pods/log\",\"pods/exec\",\"services\",\"serviceaccounts\",\"configmaps\",\"secrets\",\"persistentvolumeclaims\",\"endpoints\"],\"verbs\":[\"*\"]},{\"apiGroups\":[\"apps\"],\"resources\":[\"deployments\",\"replicasets\",\"statefulsets\",\"daemonsets\"],\"verbs\":[\"*\"]},{\"apiGroups\":[\"batch\"],\"resources\":[\"jobs\",\"cronjobs\"],\"verbs\":[\"*\"]},{\"apiGroups\":[\"networking.k8s.io\"],\"resources\":[\"ingresses\"],\"verbs\":[\"*\"]}]}', 1, '2026-08-26 10:00:00', '2026-08-26 10:00:00', NULL);

